  const validated = validateData()
  const transformed = transformData(validated)
  return saveData(transformed)
}
```

### 2. Derin İç İçe Geçme
```typescript
// FAIL: KÖTÜ: 5+ seviye iç içe geçme
if (user) {
  if (user.isAdmin) {
    if (market) {
      if (market.isActive) {
        if (hasPermission) {
          // Bir şeyler yap
        }
      }
    }
  }
}

// PASS: İYİ: Erken dönüşler
